    enonce: "<span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">B</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> ثلاث نقاط ليست على استقامة واحدة.<br><span dir=\"ltr\" class=\"expr\">(d1)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>، و <span dir=\"ltr\" class=\"expr\">(d2)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AC].</span><br><span dir=\"ltr\" class=\"expr pt\">M</span> هي نقطة تقاطع <span dir=\"ltr\" class=\"expr\">(d1)</span> و <span dir=\"ltr\" class=\"expr\">(d2).</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 187 244\" width=\"187\" height=\"244\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"38.6\" y1=\"238.0\" x2=\"181.0\" y2=\"48.1\" stroke=\"#2c3e50\" stroke-width=\"1.5\"/><text x=\"39.4\" y=\"222.6\" text-anchor=\"middle\" font-size=\"12\" font-family=\"serif\" fill=\"#6c63ff\">(d1)</text><line x1=\"6.0\" y1=\"32.3\" x2=\"181.0\" y2=\"163.6\" stroke=\"#2c3e50\" stroke-width=\"1.5\"/><text x=\"25.4\" y=\"37.1\" text-anchor=\"middle\" font-size=\"12\" font-family=\"serif\" fill=\"#6c63ff\">(d2)</text><line x1=\"36.6\" y1=\"122.0\" x2=\"150.5\" y2=\"207.4\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"36.6\" y1=\"122.0\" x2=\"100.6\" y2=\"36.6\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"150.5\" y1=\"207.4\" x2=\"100.6\" y2=\"36.6\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"125.6\" y1=\"122.0\" x2=\"36.6\" y2=\"122.0\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"125.6\" y1=\"122.0\" x2=\"150.5\" y2=\"207.4\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"125.6\" y1=\"122.0\" x2=\"100.6\" y2=\"36.6\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"68.1\" y1=\"139.4\" x2=\"62.1\" y2=\"147.4\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><line x1=\"125.0\" y1=\"182.1\" x2=\"119.0\" y2=\"190.1\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"36.6\" cy=\"122.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"23.6\" y=\"126.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"150.5\" cy=\"207.4\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"156.9\" y=\"222.7\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"100.6\" cy=\"36.6\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"100.5\" y=\"27.6\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"93.5\" cy=\"164.7\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"91.2\" y=\"181.5\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">I</text><circle cx=\"68.6\" cy=\"79.3\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"60.5\" y=\"73.1\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">K</text><circle cx=\"125.6\" cy=\"122.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"138.5\" y=\"126.7\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">M</text></svg><br>برهن أنّ<span dir=\"ltr\" class=\"expr\">: MB = MC</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">(d1)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>  و  <span dir=\"ltr\" class=\"expr\">(d2)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AC]</span>"},{"quoi":"الاختيار","math":"المطلوب : إثبات تساوي الطولين. نختار نقطة من الموسط العمودي لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr\">: (d1)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>  و  <span dir=\"ltr\" class=\"expr\">M ∈ (d1).</span> و لماذا لا عموديان على نفس المستقيم ؟ لأنّها تحتاج مستقيمين عموديين على نفس المستقيم، و لا نملك إلّا تعامدا واحدا على الأكثر."},{"quoi":"القاعدة","math":"كلّ نقطة من الموسط العمودي لقطعة متساوية البعد عن طرفيها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">(d1)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AB]</span>  و  <span dir=\"ltr\" class=\"expr\">M ∈ (d1)</span>  إذن  <span dir=\"ltr\" class=\"expr\">MA = MB</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">(d2)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[AC]</span>  و  <span dir=\"ltr\" class=\"expr\">M ∈ (d2)</span>  إذن  <span dir=\"ltr\" class=\"expr\">MA = MC</span>"},{"quoi":"القاعدة","math":"إذا كان طولان يساويان طولا ثالثا فهما متساويان"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">MB = MA</span>  و  <span dir=\"ltr\" class=\"expr\">MA = MC</span>  إذن  <span dir=\"ltr\" class=\"expr\">MB = MC</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">MB = MC</span>"}],
